CREATE OR REPLACE FUNCTION public.pro_get_visits(_from date DEFAULT (CURRENT_DATE-60),_to date DEFAULT (CURRENT_DATE+60)) RETURNS TABLE(id uuid,scheduled_start timestamptz,scheduled_end timestamptz,service_type text,street text,zip text,customer_first_name text,access_notes text,gate_code text,pet_notes text,parking_notes text,visit_pay_cents integer,status text,on_my_way_at timestamptz,completed_at timestamptz,is_sample boolean,before_photos integer,after_photos integer,visit_kind text,paid_in_full_reason text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT v.id,v.scheduled_start,v.scheduled_end,v.service_type,v.street,v.zip,v.customer_first_name,CASE WHEN v.visit_date=(now() AT TIME ZONE 'America/New_York')::date THEN v.access_notes END,CASE WHEN v.visit_date=(now() AT TIME ZONE 'America/New_York')::date THEN v.gate_code END,v.pet_notes,v.parking_notes,CASE WHEN v.size_tier=5 AND t.kind='paired_pros' THEN coalesce(public.pro_tier_uplift_cents(v.contractor_pay_cents,auth.uid()),v.visit_pay_cents)/2 ELSE v.visit_pay_cents END,v.status::text,v.on_my_way_at,v.completed_at,v.is_sample,(SELECT count(*)::integer FROM public.visit_photos p WHERE p.visit_id=v.id AND p.kind='before'),(SELECT count(*)::integer FROM public.visit_photos p WHERE p.visit_id=v.id AND p.kind='after'),v.visit_kind,v.paid_in_full_reason FROM public.visits v LEFT JOIN public.cleaning_teams t ON t.id=v.cleaning_team_id WHERE (v.assigned_pro_id=auth.uid() OR t.partner_pro_id=auth.uid()) AND (v.scheduled_start IS NULL OR v.scheduled_start::date BETWEEN _from AND _to) ORDER BY v.scheduled_start NULLS LAST $$;
CREATE OR REPLACE FUNCTION public.cleaning_finish_details(_visit uuid,_zones jsonb,_inspection boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.visits; BEGIN SELECT * INTO v FROM public.visits WHERE id=_visit; IF v.assigned_pro_id IS DISTINCT FROM auth.uid() OR v.service::text<>'cleaning' OR v.status::text IN ('complete','blocked','canceled') THEN RAISE EXCEPTION 'visit_not_assigned'; END IF; IF jsonb_typeof(_zones)<>'array' OR jsonb_array_length(_zones)>50 THEN RAISE EXCEPTION 'invalid_zones'; END IF; UPDATE public.visits SET cleaning_zones=_zones,cleaning_final_inspection_at=CASE WHEN _inspection THEN now() END WHERE id=v.id; END $$;
REVOKE ALL ON FUNCTION public.cleaning_finish_details(uuid,jsonb,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cleaning_finish_details(uuid,jsonb,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.cleaning_team_close_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.service::text='cleaning' AND NEW.size_tier=5 AND NEW.status::text='complete' AND OLD.status::text<>'complete' THEN IF NEW.cleaning_final_inspection_at IS NULL OR jsonb_array_length(NEW.cleaning_zones)=0 THEN RAISE EXCEPTION 'lead_inspection_and_zones_required'; END IF; IF NOT public.cleaning_team_valid(NEW.cleaning_team_id) THEN RAISE EXCEPTION 'team_not_verified'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER cleaning_team_close_guard BEFORE UPDATE OF status ON public.visits FOR EACH ROW EXECUTE FUNCTION public.cleaning_team_close_guard();